const prs = $input.all();

return prs
  .map(item => item.json)
  .filter(pr =>
    pr.state === 'open' &&
    !pr.head.ref.endsWith('-AI-observability') &&
    !pr.draft
  )
  .map(pr => ({
    json: {
      pr_number: pr.number,
      repository: pr.head.repo.full_name,
      title: pr.title,
      base_branch: pr.base.ref,
      head_branch: pr.head.ref,
      head_sha: pr.head.sha,
      ai_branch: `${pr.number}-AI-observability`,
      pr_url: pr.html_url
    }
  }));

const original = $("Limit").first().json;
const existing = $input.all()
  .map(item => item.json)
  .find(pr => pr.number && pr.state === 'open');

return [{
  json: {
    ...original,
    ai_branch: `${original.pr_number}-AI-observability`,
    ai_pr_exists: Boolean(existing),
    ai_pr_number: existing?.number ?? null
  }
}];
